svg.script:
(() => {
  const $ = id => document.getElementById(id);
  const weights = { major: 0.60, minor: 0.30, practice: 0.10 };

  function letterGrade(value) {
    if (!Number.isFinite(value)) return '—';
    if (value >= 97) return 'A+';
    if (value >= 93) return 'A';
    if (value >= 90) return 'A−';
    if (value >= 87) return 'B+';
    if (value >= 83) return 'B';
    if (value >= 80) return 'B−';
    if (value >= 77) return 'C+';
    if (value >= 73) return 'C';
    if (value >= 70) return 'C−';
    if (value >= 67) return 'D+';
    if (value >= 63) return 'D';
    if (value >= 60) return 'D−';
    return 'F';
  }

  function update() {
    const raw = $('currentGrade').value;
    const current = raw === '' ? null : Number(raw);
    const score = Number($('assignmentScore').value);
    const category = $('assignmentCategory').value;
    $('scoreLabel').textContent = score + '%';

    if (current === null || !Number.isFinite(current)) {
      $('currentLetter').textContent = '—';
      $('projectedGrade').innerHTML = '—<em>%</em>';
      $('projectedLetter').textContent = 'Projected: —';
      $('gradeDelta').textContent = 'Enter your current grade';
      $('gradeDelta').className = 'delta';
      return;
    }

    const safeCurrent = Math.max(0, Math.min(100, current));
    const categoryAverage = (safeCurrent + score) / 2;
    const projected = safeCurrent * (1 - weights[category]) + categoryAverage * weights[category];
    const change = projected - safeCurrent;

    $('currentLetter').textContent = letterGrade(safeCurrent);
    $('projectedGrade').innerHTML = projected.toFixed(1) + '<em>%</em>';
    $('projectedLetter').textContent = 'Projected: ' + letterGrade(projected);
    const delta = $('gradeDelta');
    delta.className = 'delta';
    if (change > 0.04) {
      delta.textContent = '↑ +' + change.toFixed(1) + ' pts';
      delta.classList.add('up');
    } else if (change < -0.04) {
      delta.textContent = '↓ ' + change.toFixed(1) + ' pts';
      delta.classList.add('down');
    } else {
      delta.textContent = '→ No change';
    }
  }

  $('currentGrade').addEventListener('input', event => {
    const value = Number(event.target.value);
    if (event.target.value !== '' && Number.isFinite(value)) {
      if (value > 100) event.target.value = 100;
      if (value < 0) event.target.value = 0;
    }
    update();
  });
  $('assignmentScore').addEventListener('input', update);
  $('assignmentCategory').addEventListener('change', update);
  update();
})();

(() => {
  const widget = document.getElementById('batteryWidget');
  const fill = document.getElementById('bwFill');
  const levelBar = document.getElementById('bwLevel');
  const percent = document.getElementById('bwPercent');
  const status = document.getElementById('bwStatus');
  const sourceTag = document.getElementById('bwSourceTag');
  const levelValue = document.getElementById('bwLevelValue');
  const unavailableNote = document.getElementById('bwUnavailable');

  if (!widget || !fill || !levelBar || !percent || !status) return;

  function paint(level, charging) {
    const pct = Math.max(0, Math.min(100, Math.round(level * 100)));
    const state = charging
      ? (pct >= 99 ? 'Fully charged' : 'Charging')
      : (pct >= 95 ? 'Battery full' : 'On battery');
    percent.textContent = pct + '%';
    if (levelValue) levelValue.textContent = pct + '%';
    fill.style.width = pct + '%';
    levelBar.style.width = pct + '%';
    widget.classList.remove('unavailable');
    if (unavailableNote) unavailableNote.hidden = true;
    widget.classList.toggle('charging', !!charging);
    widget.classList.toggle('low', pct <= 20 && !charging);
    widget.classList.toggle('full', pct >= 95);
    status.textContent = state;
    if (sourceTag) sourceTag.textContent = 'LIVE';
    widget.title = 'Chromebook battery: ' + pct + '% — ' + state;
  }

  function unavailable() {
    percent.textContent = 'N/A';
    status.textContent = 'Not available here';
    if (levelValue) levelValue.textContent = '—';
    fill.style.width = '0%';
    levelBar.style.width = '0%';
    widget.classList.add('unavailable');
    if (unavailableNote) unavailableNote.hidden = false;
    widget.classList.remove('charging', 'low', 'full');
    if (sourceTag) sourceTag.textContent = 'UNAVAILABLE';
    widget.title = 'This browser does not expose Chromebook battery information to webpages';
  }

  async function initBattery() {
    if (typeof navigator.getBattery !== 'function') {
      unavailable();
      return;
    }

    try {
      const battery = await navigator.getBattery();
      const update = () => paint(battery.level, battery.charging);
      update();
      battery.addEventListener('levelchange', update);
      battery.addEventListener('chargingchange', update);
    } catch (error) {
      unavailable();
    }
  }

  initBattery();
})();

(() => {
  const timeEl = document.getElementById('swTime');
  const dateEl = document.getElementById('swDate');
  const periodEl = document.getElementById('swPeriod');
  const leftEl = document.getElementById('swLeft');
  const progressEl = document.getElementById('swProgress');
  const widget = document.getElementById('schoolWidget');
  const scheduleToggle = document.getElementById('swScheduleToggle');
  const schedulePanel = document.getElementById('swSchedule');

  if (!timeEl || !dateEl || !periodEl || !leftEl || !progressEl ||
      !widget || !scheduleToggle || !schedulePanel) return;

  schedulePanel.style.display = 'none';
  schedulePanel.style.visibility = 'hidden';

  const schedule = [
    { id: 'Period 1', start: [7, 22], end: [8, 8] },
    { id: 'Period 2', start: [8, 12], end: [8, 59] },
    { id: 'Period 3', start: [9, 3], end: [9, 50] },
    { id: 'Period 4', start: [9, 54], end: [10, 41] },
    { id: 'Period 5', start: [10, 46], end: [12, 2] },
    { id: 'Period 6', start: [12, 8], end: [12, 52] },
    { id: 'Period 7', start: [12, 56], end: [13, 43] }
  ];

  function formatScheduleTime(parts) {
    const hour = parts[0];
    const minute = String(parts[1]).padStart(2, '0');
    const suffix = hour >= 12 ? 'PM' : 'AM';
    const displayHour = ((hour + 11) % 12) + 1;
    return displayHour + ':' + minute + ' ' + suffix;
  }

  // Schedule rows are part of the SVG markup (not inserted with innerHTML).
  // This avoids an empty popover in browsers that isolate SVG foreignObject content.
  function setScheduleOpen(open) {
    widget.classList.toggle('scheduleOpen', open);
    schedulePanel.classList.toggle('open', open);
    schedulePanel.style.display = open ? 'block' : 'none';
    schedulePanel.style.visibility = open ? 'visible' : 'hidden';
    scheduleToggle.setAttribute('aria-expanded', String(open));
    schedulePanel.setAttribute('aria-hidden', String(!open));
  }

  // Do not use a document-wide outside-click listener here: SVG event retargeting
  // can make a click inside foreignObject look like an outside click.
  scheduleToggle.addEventListener('click', event => {
    event.preventDefault();
    event.stopPropagation();
    setScheduleOpen(!schedulePanel.classList.contains('open'));
  });

  document.addEventListener('keydown', event => {
    if (event.key === 'Escape' && schedulePanel.classList.contains('open')) {
      setScheduleOpen(false);
    }
  });

  const fmtTime = new Intl.DateTimeFormat(undefined, {
    hour: 'numeric',
    minute: '2-digit',
    second: '2-digit'
  });
  const fmtDate = new Intl.DateTimeFormat(undefined, {
    weekday: 'long',
    month: 'short',
    day: 'numeric'
  });

  function minsSinceMidnight(date) {
    return date.getHours() * 60 + date.getMinutes() + date.getSeconds() / 60;
  }

  function clockString(minutes) {
    const total = Math.max(0, Math.round(minutes));
    if (total < 1) return 'less than 1 min';
    return total + (total === 1 ? ' min' : ' mins');
  }

  function paint() {
    const now = new Date();
    const weekday = now.getDay();
    const t = minsSinceMidnight(now);

    timeEl.textContent = fmtTime.format(now);
    dateEl.textContent = fmtDate.format(now);
    schedulePanel.querySelectorAll('.swScheduleItem').forEach(item => item.classList.remove('active'));
    widget.classList.remove('out');
    progressEl.style.width = '0%';

    if (weekday === 0 || weekday === 6) {
      periodEl.textContent = 'No school';
      widget.setAttribute('aria-label', 'School clock. No school today.');
      leftEl.textContent = 'Enjoy your day';
      widget.classList.add('out');
      return;
    }

    const first = schedule[0].start[0] * 60 + schedule[0].start[1];
    const last = schedule[schedule.length - 1].end[0] * 60 + schedule[schedule.length - 1].end[1];

    if (t < first || t >= last) {
      periodEl.textContent = 'Out of school';
      widget.setAttribute('aria-label', 'School clock. Outside school hours.');
      leftEl.textContent = t < first
        ? 'P1 starts at ' + formatScheduleTime(schedule[0].start)
        : 'School day over';
      widget.classList.add('out');
      return;
    }

    for (let i = 0; i < schedule.length; i++) {
      const period = schedule[i];
      const start = period.start[0] * 60 + period.start[1];
      const end = period.end[0] * 60 + period.end[1];

      if (t >= start && t < end) {
        const elapsed = t - start;
        const duration = end - start;
        const progress = Math.min(100, Math.max(0, (elapsed / duration) * 100));
        periodEl.textContent = period.id;
        widget.setAttribute('aria-label', 'School clock. Current period: ' + period.id);
        const activeItem = schedulePanel.querySelector(
          '.swScheduleItem[data-period="' + period.id + '"]'
        );
        if (activeItem) activeItem.classList.add('active');
        leftEl.textContent = clockString(end - t) + ' left';
        progressEl.style.width = progress.toFixed(2) + '%';
        return;
      }

      if (i < schedule.length - 1) {
        const next = schedule[i + 1];
        const nextStart = next.start[0] * 60 + next.start[1];

        if (t >= end && t < nextStart) {
          const gapElapsed = t - end;
          const gapDuration = nextStart - end;
          const progress = Math.min(100, Math.max(0, (gapElapsed / gapDuration) * 100));
          periodEl.textContent = 'Passing period';
          widget.setAttribute('aria-label', 'School clock. Passing period before ' + next.id + '.');
          leftEl.textContent = next.id + ' starts in ' + clockString(nextStart - t);
          progressEl.style.width = progress.toFixed(2) + '%';
          return;
        }
      }
    }
  }

  paint();
  window.setInterval(paint, 1000);
})();

(() => {
  const loader = document.getElementById('loadingScreen');
  const status = document.getElementById('loaderStatus');
  if (!loader || !status) return;

  const messages = [
    'PREPARING YOUR GRADE DASHBOARD...',
    'LOADING GRADE CATEGORIES...',
    'SETTING UP YOUR FORECAST...',
    'SYNCING THE LIVE CALCULATOR...',
    'CHECKING YOUR WORKSPACE...',
    'ALMOST READY...',
    'GRADEPILOT IS READY'
  ];

  let messageIndex = 0;
  const messageTimer = window.setInterval(() => {
    messageIndex++;
    if (messageIndex < messages.length) status.textContent = messages[messageIndex];
  }, 430);

  const reveal = () => {
    window.setTimeout(() => {
      window.clearInterval(messageTimer);
      status.textContent = 'GRADEPILOT IS READY';
      window.setTimeout(() => {
        loader.classList.add('hide');
        window.setTimeout(() => loader.remove(), 950);
      }, 300);
    }, 2600);
  };

  if (document.readyState === 'complete') reveal();
  else window.addEventListener('load', reveal, { once: true });
})();
